end

--- 해당 기능을 사용하지 않으면 지워도 무관함
function local_class:need_skip()
	return false
end

function local_class:enter()
	local master = self.characters.master()

	character_util.add_listener(master, self.controller)

	self.characters.demon_commander().Position = vector(999, 0, 999)
	self.characters.demon_governor().Position = vector(999, 0, 999)

	character_util.remove_emotion(self.characters.guest_1())
	character_util.remove_emotion(self.characters.guest_2())
end

function local_class:start()
end

function local_class:exit()
	character_util.remove_relate_event(self.characters.master(), self.controller)
end

function local_class:dispose()
	self.characters = nil
	self.controller = nil
	self.cs_controller = nil
	self.cs_section = nil
end

function local_class:on_event(e)
	if lua_helper.type_compare(e, CS.Oak.InteractEvent) then
		self:on_interact_event(e)
	end

	return false
end

function local_class:on_interact_event(e)
	if lua_helper.reference_equals(e.Target, self.characters.master()) then
		start_coroutine(self.talk_master, self)
		return true
	end

	return false
end

function local_class:talk_master()
	scene_util.play_normal_speech_action(self.characters.master(), self,
			nil,
			{ name = 'cast' },
			{ name = 'smile' },
			{ key = 'ss_slime_eatpizza_81', skip = false })
end

return local_class

