	if lua_helper.reference_equals(e.Target, self.characters.onigirl()) then
		start_coroutine(self.talk_onigirl, self)
		return true
	end

	return false
end

function local_class:talk_onigirl()
	local onigirl = self.characters.onigirl()
	-- 키리(right, smile, idle) 이미지의 위치에 서 있는 상태
	-- 상호작용시 원라인 대사 출력
	-- 키리(right, smile, idle): 번개처럼 빠른 키리님은 계속해서 빨라질테니까!
	scene_util.play_normal_speech_action(onigirl, self,
			'right',
			nil,
			{ name = 'smile', keep = true },
			{ key = 'ss_slime_onigirl_43', skip = false })
end

return local_class

